package net.minecraft.world.item;import net.minecraft.core.HolderLookup.Provider;import net.minecraft.nbt.*;public class ItemStack{public static final ItemStack EMPTY=new ItemStack("",0,"");public String id,components;public int count;public ItemStack(String id,int n,String c){this.id=id;count=n;components=c;}public boolean isEmpty(){return count<=0||id.isEmpty();}public ItemStack copy(){return isEmpty()?EMPTY:new ItemStack(id,count,components);}public int getCount(){return count;}public static boolean isSameItemSameComponents(ItemStack a,ItemStack b){return a.id.equals(b.id)&&a.components.equals(b.components);}public Tag save(Provider p){return save(p,new CompoundTag());}public Tag save(Provider p,Tag tag){CompoundTag t=(CompoundTag)tag;t.putString("id",id);t.putInt("Count",count);t.putString("Components",components);return t;}public static ItemStack parseOptional(Provider p,CompoundTag t){return new ItemStack(t.getString("id"),t.getInt("Count"),t.getString("Components"));}}